FROM employees e
JOIN departments d ON e.department_id = d.department_id;

CREATE TABLE employees (
employee_id INT PRIMARY KEY,
employee_name VARCHAR(100) NOT NULL,
department_id INT,
salary DECIMAL(10,2)
);

INSERT INTO employees
(employee_id, employee_name, department_id, salary)
VALUES (101, 'Asha', 10, 65000);

START TRANSACTION;
UPDATE accounts SET balance = balance - 1000 WHERE account_id = 1;
UPDATE accounts SET balance = balance + 1000 WHERE account_id = 2;
COMMIT;

START TRANSACTION;
UPDATE employees SET salary = salary * 2 WHERE department_id = 10;
ROLLBACK;

START TRANSACTION;
UPDATE employees SET salary = salary + 1000 WHERE department_id = 10;
SAVEPOINT salary_update;
UPDATE employees SET salary = salary + 500 WHERE department_id = 20;
ROLLBACK TO SAVEPOINT salary_update;
COMMIT;

CREATE TABLE employees (
employee_id INT PRIMARY KEY,
department_id INT,
FOREIGN KEY (department_id)
REFERENCES departments(department_id)
);

SELECT employee_name, salary
FROM employees
WHERE salary > (SELECT AVG(salary) FROM employees);

SELECT MAX(salary) AS second_highest
FROM employees
WHERE salary < (SELECT MAX(salary) FROM employees);

SELECT employee_name, salary
FROM employees
WHERE salary = (SELECT MAX(salary) FROM employees);

WITH high_earners AS (
SELECT employee_id, employee_name, salary
FROM employees
WHERE salary > 80000
)
SELECT * FROM high_earners;

WITH dept_avg AS (
SELECT department_id, AVG(salary) AS avg_salary
FROM employees
GROUP BY department_id
)
SELECT * FROM dept_avg;

SELECT employee_name, salary,
RANK() OVER (ORDER BY salary DESC) AS salary_rank
FROM employees;

WITH ranked AS (
SELECT employee_name, department_id, salary,
DENSE_RANK() OVER (
PARTITION BY department_id
ORDER BY salary DESC
) AS rnk
FROM employees
)
SELECT * FROM ranked WHERE rnk = 1;

SELECT employee_name, department_id, salary,
ROW_NUMBER() OVER (
PARTITION BY department_id
ORDER BY salary DESC
) AS row_num
FROM employees;

SELECT employee_name, hire_date, salary,
LAG(salary) OVER (ORDER BY hire_date) AS previous_salary
FROM employees;

START TRANSACTION;
UPDATE accounts SET balance = balance - 500 WHERE account_id = 1;
UPDATE accounts SET balance = balance + 500 WHERE account_id = 2;
COMMIT;

START TRANSACTION;
UPDATE employees SET salary = salary * 1.20 WHERE department_id = 10;
ROLLBACK;

START TRANSACTION;
UPDATE employees SET salary = salary + 1000 WHERE department_id = 10;
SAVEPOINT first_change;
UPDATE employees SET salary = salary + 2000 WHERE department_id = 20;
ROLLBACK TO SAVEPOINT first_change;
COMMIT;

CREATE TABLE departments (
department_id INT PRIMARY KEY,
department_name VARCHAR(100) UNIQUE NOT NULL
);

CREATE TABLE employees (
employee_id INT PRIMARY KEY,
employee_name VARCHAR(100) NOT NULL,
department_id INT,
FOREIGN KEY (department_id) REFERENCES departments(department_id)
);

CREATE TABLE customers (
customer_id INT PRIMARY KEY,
customer_name VARCHAR(100) NOT NULL
);

CREATE TABLE orders (
order_id INT PRIMARY KEY,
customer_id INT,
order_date DATE,
FOREIGN KEY (customer_id) REFERENCES customers(customer_id)
);

CREATE TABLE products (
product_id INT PRIMARY KEY,
product_name VARCHAR(100) NOT NULL
);

CREATE TABLE order_items (
order_id INT,
product_id INT,
quantity INT NOT NULL,
PRIMARY KEY (order_id, product_id),
FOREIGN KEY (order_id) REFERENCES orders(order_id),
FOREIGN KEY (product_id) REFERENCES products(product_id)
);

DELIMITER //

CREATE PROCEDURE GetEmployeesByDepartment(IN p_department_id INT)
BEGIN
SELECT employee_id, employee_name, salary
FROM employees
WHERE department_id = p_department_id;
END //

DELIMITER ;

CALL GetEmployeesByDepartment(10);

SELECT MAX(salary) AS second_highest_salary
FROM employees
WHERE salary < (SELECT MAX(salary) FROM employees);

SELECT employee_name, department_id, salary
FROM (
SELECT employee_name, department_id, salary,
DENSE_RANK() OVER (
PARTITION BY department_id
ORDER BY salary DESC
) AS rnk
FROM employees
) x
WHERE rnk = 1;

SELECT employee_name, department_id, salary
FROM (
SELECT employee_name, department_id, salary,
DENSE_RANK() OVER (
PARTITION BY department_id
ORDER BY salary DESC
) AS rnk
FROM employees
) x
WHERE rnk <= 3;

SELECT *
FROM employees
WHERE hire_date >= CURRENT_DATE - INTERVAL 30 DAY;

SELECT employee_id, employee_name
FROM employees
WHERE manager_id IS NULL;

SELECT *
FROM employees
WHERE hire_date = (SELECT MAX(hire_date) FROM employees);

SELECT *
FROM employees
WHERE hire_date = (SELECT MIN(hire_date) FROM employees);

SELECT *
FROM employees
WHERE LOWER(LEFT(employee_name, 1)) = LOWER(RIGHT(employee_name, 1));

SELECT employee_name, hire_date, salary,
SUM(salary) OVER (ORDER BY hire_date) AS running_salary
FROM employees;

SELECT employee_name, salary,
LAG(salary) OVER (ORDER BY hire_date) AS previous_salary
FROM employees;

SELECT department_id FROM departments
EXCEPT
SELECT department_id FROM employees;

